gbRz(){return"\u0648\u06cc\u0631\u0627\u06cc\u0634\u2026"},
gbRE(){return"\u0645\u06a9\u0627\u0644\u0645\u0647\u200c\u0627\u06cc \u0646\u06cc\u0633\u062a \u2014 \u06cc\u0627 \u0641\u06cc\u0644\u062a\u0631 \u0631\u0627 \u062a\u063a\u06cc\u06cc\u0631 \u062f\u0647\u06cc\u062f"},
