gbRv(){return"\u0644\u06cc\u062f\u0647\u0627"},
gaY5(){return"\u067e\u0634\u062a\u06cc\u0628\u0627\u0646"},
gbRL(){return"\u0628\u0627\u0632\u062f\u06cc\u062f\u06a9\u0646\u0646\u062f\u0647"},
gbRo(){return"\u0641\u0627\u06cc\u0644"},
gbR_(){return"\u067e\u06cc\u0648\u0633\u062a \u0641\u0627\u06cc\u0644 (\u0641\u0636\u0627\u06cc \u0630\u062e\u06cc\u0631\u0647\u200c\u0633\u0627\u0632\u06cc \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631\u060c \u0628\u0633\u062a\u0631 crm_web_chat)"},
gbRK(){return"\u067e\u0627\u0633\u062e\u2026 (Ctrl+Enter \u0627\u0631\u0633\u0627\u0644)"},
gaY6(){return"\u0627\u0631\u0633\u0627\u0644"},
gbSd(){return"\u0648\u06cc\u0631\u0627\u06cc\u0634 \u0648\u06cc\u062c\u062a \u0686\u062a"},
gbSe(){return"\u0648\u06cc\u062c\u062a \u0686\u062a \u062c\u062f\u06cc\u062f"},
gbSc(){return"\u067e\u0633 \u0627\u0632 \u0627\u06cc\u062c\u0627\u062f\u060c \xab\u06a9\u0644\u06cc\u062f \u0639\u0645\u0648\u0645\u06cc\xbb \u0648 \u0631\u0627\u0647\u0646\u0645\u0627\u06cc \u0627\u062a\u0635\u0627\u0644 API \u0627\u0632 \u0645\u0646\u0648\u06cc \u2026 \u0648\u06cc\u062c\u062a \u0642\u0627\u0628\u0644 \u06a9\u067e\u06cc \u0627\u0633\u062a. \u062f\u0627\u0645\u0646\u0647\u0654 \u0645\u062c\u0627\u0632 \u0641\u0642\u0637 \u0627\u0645\u0646\u06cc\u062a \u0645\u0631\u0648\u0631\u06af\u0631 (CORS) \u0627\u0633\u062a."},
gbSi(){return"\u0646\u0627\u0645 \u0648\u06cc\u062c\u062a (\u062f\u0627\u062e\u0644\u06cc)"},
